:root, :root[data-theme="light"] .player-frame, :root[data-theme="light"] .player:fullscreen { color-scheme: dark; --ground: #0f0b10; --well: #0b080c; --panel: #161118; --raised: #1f1822; --raised-2: #2a2130; --glass: rgba(22, 17, 24, .72); --hover: rgba(255, 236, 226, .055); --line: rgba(255, 228, 214, .08); --line-strong: rgba(255, 228, 214, .14); --ink: #f7eee9; --dim: #b9a9ab; --faint: #86767c; --glow: #ffb08a; --glow-hi: #ffc6a8; --glow-ink: #2b130c; --glow-dim: rgba(255, 176, 138, .14); --glow-line: rgba(255, 176, 138, .32); --glow-grad: linear-gradient(180deg, #ffc4a2 0%, #ff9e7c 100%); --rose: #ff8497; --mint: #7fdcae; --danger: #ff7272; --fg-rgb: 255, 228, 214; --ground-rgb: 15, 11, 16; --glow-rgb: 255, 176, 138; --glow-shadow-rgb: 255, 140, 100; --rose-rgb: 255, 132, 151; --plum-rgb: 126, 72, 150; --mint-rgb: 127, 220, 174; --danger-rgb: 255, 114, 114; --shadow-float: 0 1px 0 rgba(255, 255, 255, .04) inset, 0 18px 50px -18px rgba(0, 0, 0, .75); --shadow-pop: 0 18px 40px -12px rgba(0, 0, 0, .85); --shadow-knob: 0 2px 6px rgba(0, 0, 0, .5); --pop-bg: rgba(42, 33, 48, .95); --seg-thumb: #2a2130; --seg-thumb-shadow: inset 0 1px 0 rgba(255, 255, 255, .06), 0 4px 12px -4px rgba(0, 0, 0, .6); --knob-off: #cdbfc2; --avatar-gap: #150f17; --mine-ink: #fff4ee; --scrim: rgba(8, 5, 9, .62); --name-s: 78%; --name-l: 76%; }
:root[data-theme="light"] { color-scheme: light; --ground: #f3ebe4; --well: #fffbf8; --panel: #fbf6f2; --raised: #eee4dd; --raised-2: #e4d7cf; --glass: rgba(252, 248, 244, .74); --hover: rgba(74, 38, 48, .05); --line: rgba(74, 38, 48, .1); --line-strong: rgba(74, 38, 48, .17); --ink: #2a1b22; --dim: #65525a; --faint: #76626a; --glow: #b5481f; --glow-hi: #9a3a18; --glow-ink: #fff8f3; --glow-dim: rgba(196, 85, 44, .12); --glow-line: rgba(181, 72, 31, .34); --glow-grad: linear-gradient(180deg, #c75830 0%, #a93f1a 100%); --rose: #c93f62; --mint: #23895b; --danger: #b8322f; --fg-rgb: 74, 38, 48; --ground-rgb: 243, 235, 228; --glow-rgb: 196, 85, 44; --glow-shadow-rgb: 176, 70, 30; --rose-rgb: 201, 63, 98; --plum-rgb: 150, 104, 180; --mint-rgb: 35, 137, 91; --danger-rgb: 184, 50, 47; --shadow-float: 0 1px 0 rgba(255, 255, 255, .7) inset, 0 2px 6px -2px rgba(84, 44, 36, .08), 0 18px 44px -20px rgba(84, 44, 36, .3); --shadow-pop: 0 2px 6px -2px rgba(84, 44, 36, .1), 0 18px 40px -14px rgba(84, 44, 36, .38); --shadow-knob: 0 1px 3px rgba(84, 44, 36, .35); --pop-bg: rgba(255, 251, 248, .96); --seg-thumb: #fffdfb; --seg-thumb-shadow: 0 1px 2px rgba(84, 44, 36, .12), 0 3px 10px -4px rgba(84, 44, 36, .25); --knob-off: #ffffff; --avatar-gap: #f5eee8; --mine-ink: #2a1b22; --scrim: rgba(58, 32, 38, .32); --name-s: 62%; --name-l: 32%; }
:root { --display: "Bricolage Grotesque", "Figtree", system-ui, sans-serif; --sans: "Figtree", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; --r-sm: 10px; --r-md: 14px; --r-lg: 20px; --ease-out: cubic-bezier(.22, .8, .24, 1); --t: .18s var(--ease-out); }
* { box-sizing: border-box; }
html, body, #root { height: 100%; }
body { margin: 0px; background: var(--ground); color: var(--ink); font-family: var(--sans); font-size: 14.5px; line-height: 1.5; -webkit-font-smoothing: antialiased; overscroll-behavior: none; -webkit-tap-highlight-color: transparent; }
h1, h2 { font-family: var(--display); margin: 0px; }
button { font: inherit; color: inherit; background: none; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; cursor: pointer; padding: 0px; }
input { font: inherit; color: var(--ink); background: var(--well); border: 1px solid var(--line-strong); border-radius: var(--r-sm); padding: 11px 14px; outline: none; min-width: 0px; transition: border-color var(--t),box-shadow var(--t),background var(--t); }
input::placeholder { color: var(--faint); }
input[data-tape-hover] { border-color: rgba(var(--fg-rgb),.22); }
input[data-tape-focus-visible] { border-color: var(--glow-line); box-shadow: 0 0 0 4px var(--glow-dim); }
::selection { background: rgba(var(--glow-rgb),.3); }
[data-tape-focus-visible] { outline: 2px solid var(--glow); outline-offset: 2px; }
input[data-tape-focus-visible] { outline: none; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; border-radius: var(--r-sm); padding: 9px 16px; font-weight: 600; font-size: 14px; white-space: nowrap; border: 1px solid transparent; transition: background var(--t),border-color var(--t),color var(--t),box-shadow var(--t),filter var(--t),transform .12s var(--ease-out); }
.btn[data-tape-active]:not(:disabled) { transform: translateY(1px) scale(0.99); }
.btn:disabled { opacity: 0.38; cursor: default; }
.btn.primary { background: var(--glow-grad); color: var(--glow-ink); box-shadow: inset 0 1px #ffffff73,0 8px 22px -10px rgba(var(--glow-shadow-rgb),.7); }
.btn.primary[data-tape-hover]:not(:disabled) { filter: brightness(1.06); box-shadow: inset 0 1px #ffffff80,0 10px 28px -10px rgba(var(--glow-shadow-rgb),.85); }
.btn.primary:disabled { opacity: 1; background: var(--raised-2); color: var(--faint); box-shadow: none; }
.btn.ghost { background: var(--raised); border-color: var(--line-strong); color: var(--ink); }
.btn.ghost[data-tape-hover]:not(:disabled) { background: var(--raised-2); border-color: rgba(var(--fg-rgb),.22); }
.btn.soft { background: var(--glow-dim); border-color: rgba(var(--glow-rgb),.22); color: var(--glow-hi); }
.btn.soft[data-tape-hover]:not(:disabled) { background: rgba(var(--glow-rgb),.22); border-color: var(--glow-line); }
.btn.big { padding: 13px 20px; font-size: 15px; border-radius: var(--r-md); }
.btn.small { padding: 7px 13px; font-size: 13px; }
.icon-btn { width: 36px; height: 36px; display: inline-flex; align-items: center; justify-content: center; border-radius: var(--r-sm); color: var(--dim); flex: 0 0 auto; transition: background var(--t),color var(--t); }
.icon-btn[data-tape-hover]:not(:disabled) { color: var(--ink); background: var(--hover); }
.spinner { width: 16px; height: 16px; border-radius: 50%; border-width: 2px; border-style: solid; border-color: currentcolor transparent currentcolor currentcolor; border-image: none; display: inline-block; animation: 0.7s linear 0s infinite normal none running spin; }
.spinner.lg { width: 30px; height: 30px; border-width: 2.5px; color: var(--glow); }
@keyframes spin { 
  100% { transform: rotate(360deg); }
}
.field { display: flex; flex-direction: column; gap: 7px; text-align: left; }
.field > span { font-size: 12.5px; font-weight: 600; color: var(--dim); }
.wordmark { font-family: var(--display); font-weight: 700; letter-spacing: -0.02em; }
.avatar { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 700; color: rgb(34, 18, 26); flex: 0 0 auto; letter-spacing: 0.01em; user-select: none; }
.avatar.sm { width: 26px; height: 26px; font-size: 10px; }
.avatar.lg { width: 38px; height: 38px; font-size: 13.5px; }
.landing { position: relative; min-height: 100dvh; display: flex; flex-direction: column; padding: 22px clamp(18px, 4vw, 40px) 26px; overflow-x: hidden; }
.landing-glow { position: absolute; inset: 0px; pointer-events: none; background: radial-gradient(38% 46% at 76% 46%,rgba(var(--rose-rgb),.17),transparent 70%),radial-gradient(42% 50% at 68% 62%,rgba(var(--glow-rgb),.15),transparent 72%),radial-gradient(55% 45% at 8% 0%,rgba(var(--plum-rgb),.2),transparent 70%); }
.landing-top, .landing-main, .landing-foot { position: relative; width: 100%; max-width: 1160px; margin-inline: auto; }
.landing-top { display: flex; align-items: center; gap: 10px; }
.landing-top .wordmark { font-size: 19px; }
.landing-main { flex: 1 1 0%; display: grid; grid-template-columns: minmax(0px, 1fr) minmax(0px, 1.05fr); gap: clamp(32px, 5vw, 72px); align-items: center; padding: 40px 0px; }
.landing-copy h1 { font-size: clamp(44px, 5vw, 72px); font-weight: 750; line-height: 1; letter-spacing: -0.03em; margin-bottom: 22px; animation: rise .7s var(--ease-out) both; }
.landing-copy h1 span { color: var(--glow); white-space: nowrap; }
.landing-copy .sub { margin: 0px 0px 30px; font-size: 17px; line-height: 1.6; color: var(--dim); max-width: 44ch; animation: rise .7s 80ms var(--ease-out) both; }
.entry { max-width: 430px; display: flex; flex-direction: column; gap: 14px; padding: 22px; border-radius: 22px; background: var(--glass); border: 1px solid var(--line); backdrop-filter: blur(18px); box-shadow: var(--shadow-float); animation: rise .7s .16s var(--ease-out) both; }
.or { display: flex; align-items: center; gap: 12px; color: var(--faint); font-size: 12.5px; font-weight: 500; }
.or::before, .or::after { content: ""; flex: 1 1 0%; height: 1px; background: var(--line); }
.join-row { display: flex; gap: 8px; }
.code-input { flex: 1 1 0%; font-family: var(--display); font-weight: 700; font-size: 16px; text-transform: uppercase; letter-spacing: 0.22em; text-align: center; border-radius: var(--r-md); }
.code-input::placeholder { letter-spacing: 0.16em; font-weight: 600; }
.rejoin { align-self: center; display: inline-flex; align-items: center; gap: 8px; margin-top: 2px; padding: 6px 10px; border-radius: 999px; color: var(--dim); font-size: 13.5px; transition: color var(--t),background var(--t); }
.rejoin[data-tape-hover] { color: var(--ink); background: var(--hover); }
.rejoin b { font-family: var(--display); font-weight: 700; color: var(--glow); letter-spacing: 0.1em; }
.landing-foot { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px 18px; color: var(--faint); font-size: 13px; }
.landing-foot span + span::before { content: ""; display: inline-block; width: 4px; height: 4px; border-radius: 50%; background: currentcolor; opacity: 0.6; margin-right: 18px; vertical-align: middle; }
@keyframes rise { 
  0% { opacity: 0; transform: translateY(14px); }
}
.scene { position: relative; height: 470px; animation: rise .9s .2s var(--ease-out) both; }
.screen { position: absolute; background: linear-gradient(rgb(34, 26, 39), rgb(24, 18, 27)); border: 1px solid var(--line-strong); box-shadow: rgba(255, 255, 255, 0.05) 0px 1px inset, rgba(0, 0, 0, 0.9) 0px 40px 80px -30px, rgba(255, 150, 120, 0.45) 0px 0px 90px -40px; }
.screen.laptop { left: 0px; top: 34px; width: 80%; border-radius: 18px; padding-bottom: 14px; transform: rotate(-2.5deg); }
.screen-bar { display: flex; align-items: center; gap: 6px; padding: 11px 14px; }
.screen-bar i { width: 8px; height: 8px; border-radius: 50%; background: rgba(var(--fg-rgb),.14); }
.screen-bar span, .phone-city { font-size: 11.5px; font-weight: 600; color: var(--faint); font-variant-numeric: tabular-nums; }
.screen-bar span { margin-left: auto; }
.scene-video { margin: 0px 14px; aspect-ratio: 16 / 9; border-radius: 10px; overflow: hidden; background: rgb(58, 33, 80); }
.scene-video svg { display: block; width: 100%; height: 100%; }
.scene-video .sun { animation: 9s ease-in-out 0s infinite alternate none running sun; }
@keyframes sun { 
  100% { transform: translateY(7px); }
}
.scene-transport { display: flex; align-items: center; gap: 9px; margin: 12px 14px 0px; }
.scene-play { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; background: var(--glow-grad); color: var(--glow-ink); flex: 0 0 auto; }
.scene-track { flex: 1 1 0%; height: 4px; border-radius: 99px; background: rgba(var(--fg-rgb),.12); position: relative; }
.scene-track i { position: absolute; inset: 0px auto 0px 0px; border-radius: inherit; background: var(--glow); animation: 18s linear 0s infinite normal none running playhead; }
.scene-track i::after { content: ""; position: absolute; right: -5px; top: 50%; width: 10px; height: 10px; margin-top: -5px; border-radius: 50%; background: rgb(255, 243, 236); box-shadow: 0 0 0 3px rgba(var(--glow-rgb),.3); }
@keyframes playhead { 
  0% { width: 22%; }
  100% { width: 88%; }
}
.scene-time { font-size: 11px; font-weight: 600; color: var(--faint); font-variant-numeric: tabular-nums; }
.screen.phone { right: 0px; bottom: 0px; width: 36%; min-width: 190px; border-radius: 30px; padding: 26px 10px 14px; transform: rotate(3deg); }
.phone-notch { position: absolute; top: 10px; left: 50%; width: 46px; height: 6px; margin-left: -23px; border-radius: 99px; background: rgba(0, 0, 0, 0.55); }
.phone-city { display: block; text-align: center; margin-bottom: 9px; }
.phone .scene-video { margin: 0px; border-radius: 8px; }
.phone .scene-transport { margin: 10px 2px 0px; }
.phone-chat { display: flex; flex-direction: column; gap: 6px; margin-top: 14px; }
.phone-chat p { margin: 0px; font-size: 12px; line-height: 1.35; padding: 7px 11px; border-radius: 14px; max-width: 92%; animation: rise .5s var(--ease-out) both; }
.phone-chat .them { align-self: flex-start; background: var(--raised-2); border-bottom-left-radius: 5px; animation-delay: 0.9s; }
.phone-chat .me { align-self: flex-end; background: linear-gradient(180deg,rgba(var(--glow-rgb),.28),rgba(var(--rose-rgb),.2)); color: rgb(255, 234, 223); border-bottom-right-radius: 5px; animation-delay: 1.7s; }
.scene-sync { position: absolute; top: 0px; right: 4%; display: inline-flex; align-items: center; gap: 9px; padding: 8px 14px; border-radius: 999px; background: rgba(22, 17, 24, 0.88); border: 1px solid var(--glow-line); color: var(--glow-hi); font-size: 13px; font-weight: 600; backdrop-filter: blur(10px); box-shadow: rgba(0, 0, 0, 0.8) 0px 12px 30px -12px; }
.sync-dots { display: inline-flex; gap: 3px; }
.sync-dots i { width: 5px; height: 5px; border-radius: 50%; background: var(--glow); animation: 1.4s ease-in-out 0s infinite normal none running blink; }
.sync-dots i:nth-child(2) { animation-delay: 0.2s; }
.sync-dots i:nth-child(3) { animation-delay: 0.4s; }
@keyframes blink { 
  0%, 100% { opacity: 0.25; }
  40% { opacity: 1; }
}
@media (max-width: 900px) {
  .landing-main { grid-template-columns: 1fr; padding: 28px 0px 36px; gap: 44px; }
  .entry { max-width: 480px; }
  .scene { height: 380px; max-width: 560px; width: 100%; margin-inline: auto; }
}
@media (max-width: 520px) {
  .landing-copy h1 { font-size: clamp(40px, 12vw, 52px); }
  .landing-copy .sub { font-size: 15.5px; }
  .entry { padding: 18px; }
  .scene { height: 300px; }
  .screen.laptop { width: 88%; top: 40px; }
  .screen.phone { width: 46%; min-width: 0px; padding: 22px 8px 10px; border-radius: 24px; }
  .phone-chat p { font-size: 11px; padding: 6px 9px; }
  .scene-sync { right: 0px; font-size: 12px; padding: 7px 12px; }
}
.room { position: relative; height: 100dvh; display: flex; flex-direction: column; isolation: isolate; }
.ambient { position: fixed; inset: 0px; z-index: -1; overflow: hidden; pointer-events: none; background: var(--ground); }
.ambient-base { position: absolute; inset: 0px; background: radial-gradient(50% 45% at 32% 30%,rgba(var(--rose-rgb),.1),transparent 70%),radial-gradient(45% 45% at 42% 62%,rgba(var(--glow-rgb),.08),transparent 70%),radial-gradient(45% 50% at 100% 0%,rgba(var(--plum-rgb),.14),transparent 70%); }
.ambient-screen { position: absolute; left: 5%; top: 5%; width: 60%; height: 70%; filter: blur(80px) saturate(1.6); opacity: 0.3; transform: scale(1.3); animation: ambient-in 1.4s var(--ease-out) both; transition: opacity 1.2s; }
.ambient.live .ambient-screen { opacity: 0.5; }
.ambient-layer { position: absolute; inset: 0px; width: 100%; height: 100%; object-fit: cover; background-repeat: no-repeat; animation: 1.8s ease 0s 1 normal both running ambient-in; }
.ambient::after { content: ""; position: absolute; inset: 0px; background: radial-gradient(90% 90% at 38% 40%,transparent 30%,rgba(var(--ground-rgb),.7) 100%); }
@keyframes ambient-in { 
  0% { opacity: 0; }
}
.topbar { display: flex; align-items: center; gap: 10px; padding: 10px 16px; min-height: 60px; border-bottom: 1px solid var(--line); background: rgba(var(--ground-rgb),.5); backdrop-filter: blur(18px) saturate(1.3); z-index: 10; }
.brand { display: flex; align-items: center; gap: 9px; font-size: 16.5px; margin-right: 6px; }
.topbar-spacer { flex: 1 1 0%; }
.ticket { --stub: 66px; display: inline-flex; align-items: stretch; height: 36px; border-radius: 10px; background: linear-gradient(rgb(42, 33, 48), rgb(33, 26, 38)); border: 1px solid var(--line-strong); mask: radial-gradient(circle 5px at var(--stub) 0,#0000 96%,#000) top / 100% 51% no-repeat,radial-gradient(circle 5px at var(--stub) 100%,#0000 96%,#000) bottom / 100% 51% no-repeat; transition: border-color var(--t),background var(--t); }
.ticket[data-tape-hover] { border-color: var(--glow-line); }
.ticket-stub { width: var(--stub); display: inline-flex; align-items: center; justify-content: center; gap: 7px; font-size: 10.5px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--faint); border-right: 1.5px dashed rgba(var(--fg-rgb),.2); }
.ticket-code { display: inline-flex; align-items: center; padding: 0px 13px 0px 12px; font-family: var(--display); font-weight: 700; font-size: 15px; letter-spacing: 0.14em; color: var(--ink); transition: color var(--t); }
.ticket[data-tape-hover] .ticket-code { color: var(--glow-hi); }
.conn-dot { width: 7px; height: 7px; border-radius: 50%; flex: 0 0 auto; background: var(--faint); }
.conn-dot.online { background: var(--mint); box-shadow: 0 0 0 3px rgba(var(--mint-rgb),.16); }
.conn-dot.connecting { background: var(--glow); animation: 1.2s ease 0s infinite normal none running blink; }
.conn-dot.offline { background: var(--danger); animation: 1s ease 0s infinite normal none running blink; }
.couch { display: inline-flex; align-items: center; padding: 2px 4px 2px 2px; border-radius: 999px; transition: background var(--t); }
.couch[data-tape-hover] { background: var(--hover); }
.couch .avatar { box-shadow: 0 0 0 2.5px var(--avatar-gap); animation: pop-in .38s var(--ease-out) both; }
.couch .avatar + .avatar { margin-left: -7px; }
