[data-theme="light"] .ambient-screen { opacity: 0.22; filter: blur(90px) saturate(1.5); }
[data-theme="light"] .ambient.live .ambient-screen { opacity: 0.32; }
[data-theme="light"] .ticket { background: linear-gradient(rgb(255, 253, 251), rgb(247, 239, 233)); }
[data-theme="light"] .live-chip.offline, [data-theme="light"] .form-error { color: var(--danger); }
[data-theme="light"] .player-frame, [data-theme="light"] .player:fullscreen { color: var(--ink); }
[data-theme="light"] .player-frame { border-color: rgba(42, 22, 28, 0.9); box-shadow: rgba(84, 44, 36, 0.14) 0px 2px 4px -1px, rgba(84, 44, 36, 0.5) 0px 30px 70px -28px; }
[data-theme="light"] .room.is-live .player-frame { box-shadow: rgba(84, 44, 36, 0.14) 0px 2px 4px -1px, rgba(84, 44, 36, 0.5) 0px 30px 70px -28px, rgba(214, 110, 70, 0.45) 0px 0px 140px -40px; }
[data-theme="light"] .player:fullscreen .player-frame { border: 0px; box-shadow: none; }
[data-theme="light"] .chat-picker { background: rgba(var(--fg-rgb),.03); }
[data-theme="light"] .emoji-cats { background: rgb(246, 239, 234); }
[data-theme="light"] .queue-thumb .file { background: radial-gradient(80% 100% at 50% 120%,rgba(var(--glow-rgb),.24),transparent 70%),linear-gradient(160deg,#fbf3ed,#efe2d9); }
[data-theme="light"] .modal { box-shadow: rgba(84, 44, 36, 0.12) 0px 2px 6px -2px, rgba(84, 44, 36, 0.45) 0px 40px 90px -28px; }
[data-theme="light"] .btn.primary:disabled { color: var(--dim); }
[data-theme="light"] ::selection { background: rgba(var(--glow-rgb),.22); }
